-- Generated by generate_skill_affixes.py from D3Planner statGroups and the class catalogue.
-- K5: dc_skill_affix resolves an affix to class_id and skill_id (the BASE skill, so
-- every rune of it is boosted). skill_name stays as display text, joined on by nothing.
--
-- items_0004_skill_affixes.sql is applied and frozen; this adds the columns to what it
-- created. dc_skill_affix is world data regenerated from source, not saved player data,
-- so the recovery from a failure here is to re-import, not to restore a backup.
ALTER TABLE dc_skill_affix
  ADD COLUMN class_id INT UNSIGNED NOT NULL DEFAULT 0 AFTER affix_id,
  ADD COLUMN skill_id INT UNSIGNED NOT NULL DEFAULT 0 AFTER class_id,
  ADD KEY idx_dc_skill_affix_skill (class_id, skill_id);
