-- Backstop. No stored procedure is available, so a row left unresolved aborts by
-- selecting the same message twice into a primary key: one such row is a duplicate-key
-- error quoting the message, and none inserts nothing. The message carries no semicolon,
-- so splitting this file on semicolons stays safe.
DROP TEMPORARY TABLE IF EXISTS dc_skill_affix_abort;
CREATE TEMPORARY TABLE dc_skill_affix_abort (reason VARCHAR(190) NOT NULL, PRIMARY KEY (reason)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO dc_skill_affix_abort (reason)
  SELECT 'MIGRATION ABORTED - a dc_skill_affix row has no skill_id. Re-run generate_skill_affixes.py and re-import the affix migrations' FROM dc_skill_affix WHERE skill_id = 0
  UNION ALL
  SELECT 'MIGRATION ABORTED - a dc_skill_affix row has no skill_id. Re-run generate_skill_affixes.py and re-import the affix migrations' FROM dc_skill_affix WHERE skill_id = 0;
DROP TEMPORARY TABLE IF EXISTS dc_skill_affix_abort;
